// lib/features/ai_analysis/utils/domain_analysis.dart
import 'package:nursing_exam_poc/features/history/services/history_answer_service.dart';

/// 分野集計 1件分
class DomainAgg {
  final String name;
  int total;
  int correct;

  DomainAgg({
    required this.name,
    this.total = 0,
    this.correct = 0,
  });

  factory DomainAgg.empty(String name) => DomainAgg(name: name);

  double get rate => total == 0 ? 0.0 : correct / total;
}

/// 「必修＋10分野＋その他」を扱う分野分析ユーティリティ
class DomainAnalysis {
  /// 分野選択（必修＋10分野）の固定リスト
  static const List<String> domainOptions = [
    '必修',
    '人体の構造と機能',
    '疾病の成り立ちと回復の促進',
    '健康支援と社会保障制度',
    '成人看護学',
    '老年看護学',
    '小児看護学',
    '母性看護学',
    '精神看護学',
    '在宅看護論／地域・在宅看護論',
    '看護の統合と実践',
    'その他',
  ];

  /// 1問のレコードを「必修＋10分野＋その他」のどれかにマッピングする
  ///
  /// 分野を起点として、必要に応じて
  ///   - domain（分野）
  ///   - major（科目）
  ///   - mid（中項目）
  ///   - topic（トピック）
  /// の文字列も使って判定します。
  static String domainKeyOfRecord(AnswerRecord r) {
    // 分野起点で文字列を構成（difficulty は補助情報として後ろに付ける）
    final buf = StringBuffer();
    if (r.domain != null && r.domain!.isNotEmpty) {
      buf.write('${r.domain} ');
    }
    if (r.major != null && r.major!.isNotEmpty) {
      buf.write('${r.major} ');
    }
    if (r.mid != null && r.mid!.isNotEmpty) {
      buf.write('${r.mid} ');
    }
    if (r.topic != null && r.topic!.isNotEmpty) {
      buf.write('${r.topic} ');
    }
    // difficulty も最後に加えて、必修などを拾えるようにしておく
    final allText = '${buf.toString()} ${r.difficulty}'.trim();

    // 0) 「必修」は difficulty または他の項目に含まれていれば必修扱い
    if (r.difficulty.contains('必修') || allText.contains('必修')) {
      return '必修';
    }

    // ① 基礎3分野
    if (allText.contains('人体の構造')) {
      return '人体の構造と機能';
    }
    if (allText.contains('疾病の成り立ち') || allText.contains('回復の促進')) {
      return '疾病の成り立ちと回復の促進';
    }
    if (allText.contains('健康支援') || allText.contains('社会保障')) {
      return '健康支援と社会保障制度';
    }

    // ② 各看護学分野
    if (allText.contains('成人看護')) {
      return '成人看護学';
    }
    if (allText.contains('老年看護')) {
      return '老年看護学';
    }
    if (allText.contains('小児看護')) {
      return '小児看護学';
    }
    if (allText.contains('母性看護')) {
      return '母性看護学';
    }
    if (allText.contains('精神看護')) {
      return '精神看護学';
    }
    if (allText.contains('在宅看護論') || allText.contains('地域・在宅看護')) {
      return '在宅看護論／地域・在宅看護論';
    }
    if (allText.contains('統合と実践') || allText.contains('看護の統合')) {
      return '看護の統合と実践';
    }

    // ③ どれにも当てはまらなければその他
    return 'その他';
  }

  /// 解答履歴を「必修＋各分野」ごとに集計
  static Map<String, DomainAgg> aggregateByDomain(List<AnswerRecord> items) {
    final map = <String, DomainAgg>{};

    for (final r in items) {
      final key = domainKeyOfRecord(r);
      final agg = map.putIfAbsent(key, () => DomainAgg.empty(key));
      agg.total += 1;
      if (r.isCorrect) agg.correct += 1;
    }

    // 存在しない分野も 0 で用意（UI の並びを固定したいので）
    for (final name in domainOptions) {
      map.putIfAbsent(name, () => DomainAgg.empty(name));
    }

    return map;
  }
}

// lib/features/ai_analysis/utils/nurai_analysis.dart
import 'package:nursing_exam_poc/features/history/services/history_answer_service.dart';

/// 正答率（0.0〜1.0）
double accuracyOf(List<AnswerRecord> items) {
  if (items.isEmpty) return 0.0;
  final correct = items.where((r) => r.isCorrect).length;
  return correct / items.length;
}

Map<String, double> accuracyByDifficulty(List<AnswerRecord> items) {
  final map = <String, List<AnswerRecord>>{};
  for (final r in items) {
    final key = (r.difficulty.isEmpty) ? '未分類' : r.difficulty;
    map.putIfAbsent(key, () => <AnswerRecord>[]).add(r);
  }
  final out = <String, double>{};
  map.forEach((k, v) {
    out[k] = accuracyOf(v);
  });
  return out;
}

Map<String, double> accuracyByDomain(List<AnswerRecord> items) {
  final map = <String, List<AnswerRecord>>{};
  for (final r in items) {
    final dom =
    (r.domain == null || r.domain!.isEmpty) ? '未指定' : r.domain!.trim();
    map.putIfAbsent(dom, () => <AnswerRecord>[]).add(r);
  }
  final out = <String, double>{};
  map.forEach((k, v) {
    out[k] = accuracyOf(v);
  });
  return out;
}

/// NurAI が表示する長文の分析レポート
///
/// ※ここは「必ずコメントを出す」仕様にしている。
///   データが足りない場合は、あと何問くらい必要かも出す。
String buildNuraiAnalysisText(List<AnswerRecord> items) {
  if (items.isEmpty) {
    return 'まだ解答履歴がありません。\n\n'
        'まずは何問か問題を解いて、NurAIにあなたの「クセ」を覚えさせましょう。';
  }

  const minPerDifficulty = 5; // 形式別の比較にほしい件数
  const minPerDomain = 3; // 分野別の比較にほしい件数

  final total = items.length;
  final accAll = accuracyOf(items);
  final now = DateTime.now();

  // 直近30問・直近7日など
  final recent30 = items.take(30).toList();
  final accRecent30 = accuracyOf(recent30);

  final from7d = now.subtract(const Duration(days: 7));
  final recent7d = items.where((r) => r.ts.isAfter(from7d)).toList();
  final accRecent7d = accuracyOf(recent7d);

  // 形式別・分野別の正答率
  final byDiff = accuracyByDifficulty(items);
  final byDom = accuracyByDomain(items);

  // 件数カウント（コメント用）
  final countByDiff = <String, int>{};
  final countByDom = <String, int>{};

  for (final r in items) {
    final d = (r.difficulty.isEmpty) ? '未分類' : r.difficulty;
    countByDiff[d] = (countByDiff[d] ?? 0) + 1;

    final dom =
    (r.domain == null || r.domain!.isEmpty) ? '未指定' : r.domain!.trim();
    countByDom[dom] = (countByDom[dom] ?? 0) + 1;
  }

  // 得意・苦手分野（ドメイン）
  final domainEntries = byDom.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));

  final bestDomains = domainEntries.take(2).toList();
  final worstDomains =
  domainEntries.reversed.take(2).toList().reversed.toList();

  String pct(double v) => '${(v * 100).toStringAsFixed(1)}%';

  final buffer = StringBuffer();

  // ① コンセプトメッセージ
  buffer.writeln(
      'NurAIのAI分析は、あなたが解いた問題の履歴から「得意」と「苦手」のパターンを学習し続ける、育成型コーチです。');
  buffer.writeln('解けば解くほど、NurAIはあなた専用の先生として賢くなっていきます。');
  buffer.writeln();

  // ② 全体の振り返り
  buffer.writeln('【全体のようす】');
  buffer.writeln('・これまでの解答数：$total 問');
  buffer.writeln('・総合正答率　　　：${pct(accAll)}');

  if (recent30.length >= 10) {
    buffer.writeln('・直近30問の正答率：${pct(accRecent30)}');
  }
  if (recent7d.length >= 10) {
    buffer.writeln('・直近7日間の正答率：${pct(accRecent7d)}');
  }

  if (recent7d.length >= 10) {
    if (accRecent7d > accAll + 0.05) {
      buffer.writeln('→ 直近は全体よりも正答率が高く、良いペースで成長しています。');
    } else if (accRecent7d < accAll - 0.05) {
      buffer.writeln('→ 直近は少し調子を崩し気味かもしれません。焦らず復習中心で立て直しましょう。');
    } else {
      buffer.writeln('→ 直近の成績は全体と同程度で、安定した状態です。');
    }
  }
  buffer.writeln();

  // ③ 出題形式別
  buffer.writeln('【出題形式ごとの傾向】');

  if (byDiff.isEmpty) {
    buffer.writeln('まだ出題形式ごとのデータが十分ではありません。'
        '必修・一般・状況設定をバランスよく解いていくと、形式ごとの得意・不得意が見えてきます。');
    buffer.writeln();
  } else {
    buffer.writeln('【出題形式別の成績】');

    const order = ['必修問題', '一般問題', '状況設定問題'];
    final keys = [
      ...order.where((k) => byDiff.containsKey(k)),
      ...byDiff.keys.where((k) => !order.contains(k)),
    ];

    for (final k in keys) {
      final v = byDiff[k]!;
      final c = countByDiff[k] ?? 0;
      buffer.writeln('・$k：${pct(v)}（$c 問）');
    }
    buffer.writeln();

    // 形式ごとの比較コメント
    final eligibleDiffs = keys
        .where((k) => (countByDiff[k] ?? 0) >= minPerDifficulty)
        .toList();

    if (eligibleDiffs.length >= 2) {
      eligibleDiffs.sort(
            (a, b) => byDiff[b]!.compareTo(byDiff[a]!),
      );
      final bestKey = eligibleDiffs.first;
      final worstKey = eligibleDiffs.last;

      buffer.writeln(
          '今のところ一番戦えているのは「$bestKey」で、この形式はかなり安定して得点できています。');
      if (bestKey != worstKey) {
        buffer.writeln(
            '逆に「$worstKey」は、まだ伸びしろたっぷりのポジションです。ここを鍛えられれば、全体の底上げにつながっていきます。');
      }
    } else {
      // データ不足の場合は、具体的にあと何問かを書く
      buffer.writeln(
          '出題形式ごとの差をはっきり評価するには、各形式少なくとも $minPerDifficulty 問程度のデータがあると安心です。');
      buffer.writeln('いまのところ、次の形式でデータがやや不足しています：');
      for (final k in keys) {
        final c = countByDiff[k] ?? 0;
        final need = (minPerDifficulty - c).clamp(0, minPerDifficulty);
        if (need > 0) {
          buffer.writeln('・$k：あと $need 問 ほど解くと傾向が見えやすくなります。');
        }
      }
    }
    buffer.writeln();
  }

  // ④ 分野別の強み・弱み
  buffer.writeln('【分野別の強みと課題】');

  if (domainEntries.isEmpty) {
    buffer.writeln('まだ分野情報つきの問題がほとんど無いため、「どの分野が得意か／苦手か」を評価できる段階ではありません。');
    buffer.writeln(
        '今後、成人・老年・精神など、複数の領域の問題を解いていくことで、分野ごとの傾向が見えてきます。');
    buffer.writeln();
  } else {
    buffer.writeln('【分野別の成績概要】');
    for (final e in domainEntries) {
      final c = countByDom[e.key] ?? 0;
      buffer.writeln('・${e.key}：${pct(e.value)}（$c 問）');
    }
    buffer.writeln();

    // 比較に使える分野（ある程度の問題数があるもの）
    final eligibleDomains = domainEntries
        .where((e) => (countByDom[e.key] ?? 0) >= minPerDomain)
        .toList();

    if (eligibleDomains.length >= 2) {
      eligibleDomains.sort((a, b) => b.value.compareTo(a.value));
      final best = eligibleDomains.first;
      final worst = eligibleDomains.last;

      buffer.writeln('■ 比較的得意な分野');
      buffer.writeln(
          '・${best.key}：${pct(best.value)}（${countByDom[best.key] ?? 0} 問）');
      buffer.writeln(
          '　→ この分野はかなり安定して得点できており、自信を持って良い領域です。');
      buffer.writeln();

      buffer.writeln('■ 集中して伸ばしたい分野');
      buffer.writeln(
          '・${worst.key}：${pct(worst.value)}（${countByDom[worst.key] ?? 0} 問）');
      buffer.writeln(
          '　→ 迷いやすいパターンが残っている可能性があります。頻出テーマを中心に、基礎の整理と解き直しをしておくと安心です。');
      buffer.writeln();
    } else {
      // 分野はあるが、件数や分野数が足りないとき
      buffer.writeln(
          '分野ごとの強み・課題をはっきり評価するには、1つの分野につき少なくとも $minPerDomain 問程度、'
              'かつ2つ以上の分野でデータがあると安心です。');
      buffer.writeln('現在の不足状況の目安は次のとおりです：');

      for (final e in domainEntries) {
        final c = countByDom[e.key] ?? 0;
        final need = (minPerDomain - c).clamp(0, minPerDomain);
        if (need > 0) {
          buffer.writeln('・${e.key}：あと $need 問 ほど解くと傾向が見えやすくなります。');
        }
      }

      if (domainEntries.length < 2) {
        buffer.writeln(
            'また、現時点では分野のバリエーション自体も少なめです。別の領域の問題にも少しずつ触れてみると、全体像がつかみやすくなります。');
      }
      buffer.writeln();
    }
  }

  // ⑤ これからの学び方の提案
  buffer.writeln('【これからの学び方の提案】');
  if (worstDomains.isNotEmpty) {
    buffer.writeln('1. まずは「${worstDomains.first.key}」を優先して復習しましょう。');
    buffer.writeln('   ・スコア画面から、該当分野の問題だけを解き直すのがおすすめです。');
  } else {
    buffer.writeln('1. まずは苦手分野を見つけるために、さまざまな分野の問題をバランスよく解いてみましょう。');
  }

  if (byDiff['状況設定問題'] != null &&
      byDiff['状況設定問題']! < accAll - 0.05) {
    buffer.writeln(
        '2. 状況設定問題は臨床イメージが重要です。慌てず文章を区切って読み、「誰が」「いつ」「どこで」「何に困っているか」を整理してから選択肢を見る練習をしてみてください。');
  } else {
    buffer.writeln(
        '2. 本番に近い形でトレーニングしたい場合は、「模試モード」で連続して解く練習も取り入れてみましょう。');
  }

  buffer.writeln(
      '3. 正解した問題も、理由を説明できるか自分に問いかけてみてください。説明できない正解は、たまたま当たった可能性があります。');
  buffer.writeln();

  // ⑥ NurAI からの一言
  buffer.writeln('【NurAIからのひとこと】');
  if (accAll >= 0.8) {
    buffer.writeln(
        'かなり高い正答率です。この調子なら、本番に向けて「抜け漏れを埋める仕上げフェーズ」に入っていけそうです。'
            '難易度の高い問題にも挑戦してみましょう。');
  } else if (accAll >= 0.6) {
    buffer.writeln(
        '着実に力がついてきています。あと一歩伸ばすには、間違えた問題の振り返りと、状況設定問題への慣れが鍵になりそうです。');
  } else {
    buffer.writeln(
        'まだ伸びしろがたくさんある状態です。最初は正答率よりも「毎日触ること」を大事にしていきましょう。'
            'NurAIは、あなたが解けば解くほど、あなたのパターンを学習して賢くなっていきます。');
  }

  return buffer.toString();
}

// lib/features/ai_analysis/domain/record_structure_enricher.dart
import 'package:nursing_exam_poc/features/history/services/history_answer_service.dart';
import 'package:nursing_exam_poc/features/ai_analysis/services/classification_service.dart';

/// ----------------------------------------------
/// 解答履歴の構造情報（major / mid / topic）を
/// LLM を使って自動補完するユーティリティ
/// ----------------------------------------------
class RecordStructureEnricher {
  /// 1回の分析で LLM に問い合わせる最大件数
  /// （コスト・時間を抑えるための上限）
  static const int maxEnrichCount = 50;

  /// 与えられた AnswerRecord のリストに対して、
  /// major / mid / topic がすべて空のものだけ LLM で補完して返す。
  /// すでに値が入っているレコードはそのまま返却する。
  static Future<List<AnswerRecord>> enrichAll(
      List<AnswerRecord> records,
      ) async {
    if (records.isEmpty) return records;

    final List<AnswerRecord> result = [];
    int enrichedCount = 0;

    for (final r in records) {
      if (_needsEnrich(r) && enrichedCount < maxEnrichCount) {
        final enriched = await enrichOne(r);
        result.add(enriched);
        enrichedCount++;
      } else {
        result.add(r);
      }
    }

    return result;
  }

  /// 単一レコードについて、major / mid / topic を補完した
  /// 新しい AnswerRecord を返す。
  ///
  /// すでにいずれかが埋まっている場合は、そのまま返す。
  static Future<AnswerRecord> enrichOne(AnswerRecord record) async {
    if (!_needsEnrich(record)) {
      return record;
    }

    // LLM で major / mid / topic を推定
    final classified = await ClassificationService.classifyStructure(
      question: record.question,
      difficulty: record.difficulty,
    );

    final major = _normalize(classified['major']);
    final mid = _normalize(classified['mid']);
    final topic = _normalize(classified['topic']);

    return record.copyWith(
      major: major,
      mid: mid,
      topic: topic,
    );
  }

  /// major / mid / topic がすべて空かどうか判定
  static bool _needsEnrich(AnswerRecord r) {
    return _isNullOrEmpty(r.major) &&
        _isNullOrEmpty(r.mid) &&
        _isNullOrEmpty(r.topic);
  }

  static bool _isNullOrEmpty(String? v) {
    if (v == null) return true;
    return v.trim().isEmpty;
  }

  /// LLM から返ってきた文字列を軽く正規化
  static String _normalize(String? v) {
    if (v == null) return '未分類';
    final trimmed = v.trim();
    if (trimmed.isEmpty) return '未分類';
    return trimmed;
  }
}

// lib/features/ai_analysis/models/ai_analysis_models.dart

/// AI分析の口調
enum AnalysisTone {
  gentle,   // やさしい
  neutral,  // 標準
  strict,   // やや厳しめ
  coach,    // 熱血コーチ
  clinical, // 医療従事者向け・専門的
}

extension AnalysisToneExt on AnalysisTone {
  String get id {
    switch (this) {
      case AnalysisTone.gentle:
        return 'gentle';
      case AnalysisTone.neutral:
        return 'neutral';
      case AnalysisTone.strict:
        return 'strict';
      case AnalysisTone.coach:
        return 'coach';
      case AnalysisTone.clinical:
        return 'clinical';
    }
  }

  String get label {
    switch (this) {
      case AnalysisTone.gentle:
        return 'やさしい';
      case AnalysisTone.neutral:
        return '標準';
      case AnalysisTone.strict:
        return 'やや厳しめ';
      case AnalysisTone.coach:
        return '熱血コーチ風';
      case AnalysisTone.clinical:
        return '専門家コメント風';
    }
  }

  String get description {
    switch (this) {
      case AnalysisTone.gentle:
        return '励まし多めで、メンタルにやさしいコメントを行います。';
      case AnalysisTone.neutral:
        return 'フラットで落ち着いたトーンで、事実ベースにコメントします。';
      case AnalysisTone.strict:
        return 'やや厳しめに課題を指摘し、改善ポイントをはっきり伝えます。';
      case AnalysisTone.coach:
        return '熱血指導風に、前向きなエネルギー強めでコメントします。';
      case AnalysisTone.clinical:
        return '医療従事者向けの、やや専門的で臨床寄りのコメントを行います。';
    }
  }

  static AnalysisTone fromId(String id) {
    switch (id) {
      case 'gentle':
        return AnalysisTone.gentle;
      case 'neutral':
        return AnalysisTone.neutral;
      case 'strict':
        return AnalysisTone.strict;
      case 'coach':
        return AnalysisTone.coach;
      case 'clinical':
        return AnalysisTone.clinical;
      default:
        return AnalysisTone.neutral;
    }
  }
}

/// 出題形式の統計
class DifficultyStat {
  final String name;
  final int total;
  final int correct;

  const DifficultyStat({
    required this.name,
    required this.total,
    required this.correct,
  });

  double get rate => total == 0 ? 0.0 : correct / total;
}

/// 分野の統計
class DomainStat {
  final String name;
  final int total;
  final int correct;

  const DomainStat({
    required this.name,
    required this.total,
    required this.correct,
  });

  double get rate => total == 0 ? 0.0 : correct / total;
}

/// AI分析の結果モデル
class AiAnalysisResult {
  final int totalAnswers;
  final double overallAccuracy;

  final String introMessage;
  final String difficultyComment;
  final String domainComment;
  final String studyAdvice;
  final String nuraiComment;

  final List<DifficultyStat> difficultyStats;
  final List<DomainStat> domainStats;

  const AiAnalysisResult({
    required this.totalAnswers,
    required this.overallAccuracy,
    required this.introMessage,
    required this.difficultyComment,
    required this.domainComment,
    required this.studyAdvice,
    required this.nuraiComment,
    this.difficultyStats = const <DifficultyStat>[],
    this.domainStats = const <DomainStat>[],
  });
}

