import 'dart:convert';
import 'package:flutter/foundation.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// 解答履歴 1件分（スナップショット保存型）
///
/// Phase0/1/2 の拡張に対応：
/// - 可変択数 `choiceCount`
/// - 設問タイプ `questionKind` ('single' / 'multiple' / 'select_incorrect')
/// - 複数解答 `userAnswers` / 複数正答 `correctAnswers`
///
/// さらに過去問連携用に：
/// - `sourceType`: 'ai' / 'past_exam' など
/// - `sourceTag` : '第113回 必修 午前 1問' など、問題の識別タグ
///
/// 後方互換：旧データ（単一解答）も自動で配列化して読み込みます。
class AnswerRecord {
  final String id; // 例: epoch_ms 文字列
  final DateTime ts; // タイムスタンプ
  final String difficulty; // '必修問題' / '一般問題' / '状況設定問題'
  final String? domain; // 分野
  final String? major; // 大項目
  final String? mid; // 中項目
  final String? topic; // 小項目（内部選定）

  // スナップショット（本文）
  final String question;
  final Map<String, String> choices; // 'A'.. : '本文'
  final String? explanation; // 解説
  final Map<String, String>? rationales; // 可能なら

  // --- Phase 拡張 ---
  final int choiceCount; // 4/5...（未指定時は choices.length を採用）
  final String questionKind; // 'single' / 'multiple' / 'select_incorrect'
  final List<String> userAnswers; // ユーザー選択（複数対応）
  final List<String> correctAnswers; // 正答（複数対応）

  // --- ソース情報（AI / 過去問 などの区別用） ---
  /// 'ai', 'past_exam' など。未指定の場合は null。
  final String? sourceType;

  /// 例: '第113回 必修 午前 1問' など、問題を一意に識別しやすいタグ
  final String? sourceTag;

  // --- 互換getter（旧UI用） ---
  String? get userAnswer => userAnswers.isNotEmpty ? userAnswers.first : null;
  String get correct => correctAnswers.isNotEmpty ? correctAnswers.first : '';

  /// 正誤判定
  ///
  /// ✅ 仕様（どの questionKind でも共通）:
  ///   - ユーザーの選択集合 == 正答集合 のときだけ「正解」
  ///   - つまり
  ///       * 1つでも足りない
  ///       * 1つでも余計に選んでいる
  ///       * 1つも合っていない
  ///     → すべて不正解
  ///
  ///   - multiple のとき:
  ///       正解が A,C → ユーザーが A,C を両方選んだときだけ正解
  ///   - select_incorrect のとき:
  ///       「誤っている選択肢ラベルの集合」と完全一致したときだけ正解
  bool get isCorrect {
    final ua = userAnswers.toSet();
    final ca = correctAnswers.toSet();

    if (ua.isEmpty || ca.isEmpty) return false;

    // ★ 完全一致（順不同）でのみ正解とする
    return ua.length == ca.length && ua.containsAll(ca);
  }

  const AnswerRecord({
    required this.id,
    required this.ts,
    required this.difficulty,
    required this.domain,
    required this.major,
    required this.mid,
    required this.topic,
    required this.question,
    required this.choices,
    required this.explanation,
    required this.rationales,
    this.choiceCount = 4,
    this.questionKind = 'single',
    List<String>? userAnswers,
    List<String>? correctAnswers,
    this.sourceType,
    this.sourceTag,
  })  : userAnswers = userAnswers ?? const <String>[],
        correctAnswers = correctAnswers ?? const <String>[];

  /// 後方互換を考慮した読み込み
  factory AnswerRecord.fromJson(Map<String, dynamic> j) {
    final version = (j['schemaVersion'] as int?) ?? 1;

    // 共通部の取り出し（壊れ値に強く）
    DateTime _parseTs(dynamic v) {
      if (v is int) return DateTime.fromMillisecondsSinceEpoch(v);
      if (v is String) {
        final p = DateTime.tryParse(v);
        if (p != null) return p;
        final asInt = int.tryParse(v);
        if (asInt != null) return DateTime.fromMillisecondsSinceEpoch(asInt);
      }
      return DateTime.now();
    }

    Map<String, String> _parseChoices(dynamic m) {
      if (m is Map) {
        return m.map((k, v) => MapEntry(k.toString(), v.toString()));
      }
      return const <String, String>{};
    }

    final id = (j['id'] ?? '').toString();
    final ts = _parseTs(j['ts']);
    final difficulty = (j['difficulty'] ?? '').toString();
    final domain = j['domain']?.toString();
    final major = j['major']?.toString();
    final mid = j['mid']?.toString();
    final topic = j['topic']?.toString();
    final question = (j['question'] ?? '').toString();
    final choices = _parseChoices(j['choices']);
    final explanation = j['explanation']?.toString();
    final rationales = (j['rationales'] is Map)
        ? (j['rationales'] as Map)
        .map((k, v) => MapEntry(k.toString(), v.toString()))
        : null;

    // 新フィールド（あってもなくてもOK）
    final sourceType = j['sourceType']?.toString();
    final sourceTag = j['sourceTag']?.toString();

    // ラベル正規化（' a ' → 'A'）
    List<String> _normList(dynamic any) {
      if (any is List) {
        final set = <String>{};
        for (final e in any) {
          final s = e?.toString().trim().toUpperCase() ?? '';
          if (s.isNotEmpty) set.add(s);
        }
        final out = set.toList()..sort();
        return out;
      }
      return const <String>[];
    }

    // choiceCount の妥当化（未指定は choices.length、最低2）
    int _resolveChoiceCount(int? raw) {
      final fromChoices = choices.length;
      final n = raw ?? fromChoices;
      return n.clamp(2, 26);
    }

    if (version >= 2) {
      final cc = _resolveChoiceCount(j['choiceCount'] as int?);
      final kind = (j['questionKind'] ?? 'single').toString();
      final ua = _normList(j['userAnswers']);
      final ca = _normList(j['correctAnswers']);
      return AnswerRecord(
        id: id,
        ts: ts,
        difficulty: difficulty,
        domain: domain,
        major: major,
        mid: mid,
        topic: topic,
        question: question,
        choices: choices,
        explanation: explanation,
        rationales: rationales,
        choiceCount: cc,
        questionKind: kind,
        userAnswers: ua,
        correctAnswers: ca,
        sourceType: sourceType,
        sourceTag: sourceTag,
      );
    } else {
      // 旧形式 → 新形式に変換
      final ua = j['userAnswer']?.toString();
      final ca = j['correct']?.toString();

      final uaList = <String>[];
      final caList = <String>[];
      if (ua != null && ua.trim().isNotEmpty) {
        uaList.add(ua.trim().toUpperCase());
      }
      if (ca != null && ca.trim().isNotEmpty) {
        caList.add(ca.trim().toUpperCase());
      }

      return AnswerRecord(
        id: id,
        ts: ts,
        difficulty: difficulty,
        domain: domain,
        major: major,
        mid: mid,
        topic: topic,
        question: question,
        choices: choices,
        explanation: explanation,
        rationales: rationales,
        choiceCount: _resolveChoiceCount(4),
        questionKind: 'single',
        userAnswers: uaList,
        correctAnswers: caList,
        sourceType: sourceType,
        sourceTag: sourceTag,
      );
    }
  }

  Map<String, dynamic> toJson() => {
    'schemaVersion': 2,
    'id': id,
    'ts': ts.millisecondsSinceEpoch,
    'difficulty': difficulty,
    'domain': domain,
    'major': major,
    'mid': mid,
    'topic': topic,
    'question': question,
    'choices': choices,
    'explanation': explanation,
    'rationales': rationales,
    'choiceCount': choiceCount,
    'questionKind': questionKind,
    'userAnswers': userAnswers,
    'correctAnswers': correctAnswers,
    'sourceType': sourceType,
    'sourceTag': sourceTag,
  };

  AnswerRecord copyWith({
    String? id,
    DateTime? ts,
    String? difficulty,
    String? domain,
    String? major,
    String? mid,
    String? topic,
    String? question,
    Map<String, String>? choices,
    String? explanation,
    Map<String, String>? rationales,
    int? choiceCount,
    String? questionKind,
    List<String>? userAnswers,
    List<String>? correctAnswers,
    String? sourceType,
    String? sourceTag,
  }) {
    return AnswerRecord(
      id: id ?? this.id,
      ts: ts ?? this.ts,
      difficulty: difficulty ?? this.difficulty,
      domain: domain ?? this.domain,
      major: major ?? this.major,
      mid: mid ?? this.mid,
      topic: topic ?? this.topic,
      question: question ?? this.question,
      choices: choices ?? this.choices,
      explanation: explanation ?? this.explanation,
      rationales: rationales ?? this.rationales,
      choiceCount: choiceCount ?? this.choiceCount,
      questionKind: questionKind ?? this.questionKind,
      userAnswers: userAnswers ?? this.userAnswers,
      correctAnswers: correctAnswers ?? this.correctAnswers,
      sourceType: sourceType ?? this.sourceType,
      sourceTag: sourceTag ?? this.sourceTag,
    );
  }
}

/// 履歴の保存・取得（SharedPreferences, List<String>）
/// - ストレージキー: 'answer_history_v3'
/// - 1件=1JSON文字列 で先頭挿入（最新が先頭）
/// - 破損エントリはスキップして読み込む
class AnswerHistory {
  AnswerHistory._();
  static final AnswerHistory instance = AnswerHistory._();

  static const _storageKey = 'answer_history_v3';
  static const _maxKeep = 500;

  /// 🔔 履歴が変わるたびにインクリメントされる「バージョン」
  /// これを監視することで、UI側が自動で再読み込みできる
  final ValueNotifier<int> _version = ValueNotifier<int>(0);
  ValueListenable<int> get versionListenable => _version;

  Future<List<AnswerRecord>> all() async {
    final sp = await SharedPreferences.getInstance();
    final raw = sp.getStringList(_storageKey) ?? const <String>[];

    final out = <AnswerRecord>[];
    for (final s in raw) {
      try {
        final obj = jsonDecode(s);
        if (obj is Map<String, dynamic>) {
          out.add(AnswerRecord.fromJson(obj));
        } else if (obj is Map) {
          out.add(AnswerRecord.fromJson(Map<String, dynamic>.from(obj)));
        }
      } catch (_) {
        // 壊れたエントリはスキップ
      }
    }
    return out;
  }

  Future<void> add(AnswerRecord rec) async {
    final sp = await SharedPreferences.getInstance();
    final list = sp.getStringList(_storageKey) ?? <String>[];
    list.insert(0, jsonEncode(rec.toJson()));
    if (list.length > _maxKeep) {
      list.removeRange(_maxKeep, list.length);
    }
    await sp.setStringList(_storageKey, list);

    // 🔔 UIに「変わったよ」と知らせる
    _version.value++;
  }

  /// 1件削除（id一致）
  ///
  /// - 1件=1JSON文字列 なので decode して id を確認
  /// - 壊れたエントリは「削除対象ではない」として残す（all() と同じ思想）
  Future<void> removeById(String id) async {
    final sp = await SharedPreferences.getInstance();
    final list = sp.getStringList(_storageKey) ?? <String>[];

    if (list.isEmpty) return;

    final before = list.length;

    list.removeWhere((s) {
      try {
        final obj = jsonDecode(s);
        if (obj is Map) {
          final rid = (obj['id'] ?? '').toString();
          return rid == id;
        }
      } catch (_) {
        // 壊れデータはここでは消さない（安全優先）
      }
      return false;
    });

    if (list.length == before) return;

    await sp.setStringList(_storageKey, list);

    // 🔔 UIに「変わったよ」と知らせる
    _version.value++;
  }

  Future<void> clear() async {
    final sp = await SharedPreferences.getInstance();
    await sp.remove(_storageKey);

    // 🔔 クリアしたことも通知
    _version.value++;
  }
}

// lib/features/mock_exam/logic/mock_exam_controller.dart
import 'dart:async';
import 'dart:math';

import 'package:flutter/material.dart';

import '../../../questioning/engine/question_engine.dart';
import '../../history/services/history_answer_service.dart';
import '../models/mock_exam_result_data.dart';
import '../models/mock_exam_state.dart';
import 'mock_exam_planner.dart';
import 'mock_exam_prefetch_controller.dart';

class MockExamController extends ChangeNotifier {
  MockExamController({
    required this.questionCount,
    required this.examType,
    required this.timeLimitMinutes,
  }) : _rand = Random(DateTime.now().microsecondsSinceEpoch) {
    _totalSeconds = timeLimitMinutes * 60;
    _remainingSeconds = _totalSeconds;
  }

  final int questionCount;
  final String examType;
  final int timeLimitMinutes;

  final MockExamPrefetchController _prefetchController =
  MockExamPrefetchController();
  final Random _rand;

  final MockExamState state = MockExamState();

  late final int _totalSeconds;
  Timer? _timer;

  int _currentIndex = 0;
  bool _finished = false;
  bool _finishedByTimeout = false;
  int _remainingSeconds = 0;

  final List<AnswerRecord> _records = [];

  int get currentIndex => _currentIndex;
  bool get finished => _finished;
  bool get finishedByTimeout => _finishedByTimeout;
  int get totalSeconds => _totalSeconds;
  int get remainingSeconds => _remainingSeconds;

  bool get isLoading => state.isLoading;

  String? get questionText => state.questionText;
  Map<String, String>? get choices => state.choices;
  List<String>? get correctAnswers => state.correctAnswers;
  String? get explanation => state.explanation;
  Map<String, String>? get rationales => state.rationales;
  Set<String> get userAnswers => state.userAnswers;
  String get questionKind => state.questionKind;
  Map<String, dynamic>? get meta => state.meta;

  List<AnswerRecord> get records => List.unmodifiable(_records);

  bool get hasTimeLimit => _totalSeconds > 0;

  bool get isMulti =>
      state.questionKind == 'multiple' ||
          state.questionKind == 'select_incorrect' ||
          (state.correctAnswers?.length ?? 0) >= 2;

  void start() {
    if (_totalSeconds > 0) {
      _startTimer();
    }
    loadCurrentQuestionFirst();
  }

  @override
  void dispose() {
    _timer?.cancel();
    _prefetchController.dispose();
    super.dispose();
  }

  void selectSingle(String value) {
    state.userAnswers = {value};
    notifyListeners();
  }

  void toggleMultiple(String value) {
    if (state.userAnswers.contains(value)) {
      state.userAnswers.remove(value);
    } else {
      state.userAnswers.add(value);
    }
    notifyListeners();
  }

  void _startTimer() {
    _timer?.cancel();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (_finished) return;

      _remainingSeconds -= 1;
      if (_remainingSeconds < 0) {
        _remainingSeconds = 0;
      }
      notifyListeners();

      if (_remainingSeconds <= 0) {
        finishExam(byTimeout: true);
      }
    });
  }

  Future<void> loadCurrentQuestionFirst() async {
    state.isLoading = true;
    notifyListeners();

    try {
      final q = await _fetchQuestionForIndex(_currentIndex);
      _applyQuestion(q);
      _kickPrefetch();
    } finally {
      state.isLoading = false;
      notifyListeners();
    }
  }

  Future<void> goNext() async {
    if (_finished) return;

    final nextIndex = _currentIndex + 1;
    if (nextIndex >= questionCount) {
      finishExam(byTimeout: false);
      return;
    }

    _currentIndex = nextIndex;
    state.isLoading = true;
    state.clearQuestion();
    notifyListeners();

    try {
      final ready = _prefetchController.consumeIfReady(nextIndex);
      if (ready != null) {
        _applyQuestion(ready);
        _kickPrefetch();
        return;
      }

      if (_prefetchController.inFlight != null) {
        try {
          final q = await _prefetchController.inFlight!;
          if (q.index == nextIndex) {
            _prefetchController.clearCache();
            _applyQuestion(q);
            _kickPrefetch();
            return;
          }
        } catch (_) {
          _prefetchController.clearCache();
        }
      }

      final q = await _fetchQuestionForIndex(nextIndex);
      _applyQuestion(q);
      _kickPrefetch();
    } finally {
      state.isLoading = false;
      notifyListeners();
    }
  }

  Future<void> submitCurrent() async {
    if (state.questionText == null ||
        state.choices == null ||
        state.correctAnswers == null) {
      throw StateError('問題を読み込んでから解答してください。');
    }
    if (state.userAnswers.isEmpty) {
      throw StateError('選択肢を選んでください。');
    }

    final rec = AnswerRecord(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      ts: DateTime.now(),
      difficulty:
      state.currentDifficulty ?? (state.meta?['difficulty']?.toString() ?? ''),
      domain: (state.meta?['domain'] as String?) ?? state.currentDomain,
      major: (state.meta?['major'] as String?) ?? state.currentMajor,
      mid: (state.meta?['mid'] as String?) ?? state.currentMid,
      topic: (state.meta?['topic'] as String?) ?? state.currentTopic,
      question: state.questionText!,
      choices: state.choices!,
      explanation: state.explanation,
      rationales: state.rationales,
      choiceCount: state.choices!.length,
      questionKind: state.questionKind,
      userAnswers: state.userAnswers.toList()..sort(),
      correctAnswers: state.correctAnswers!..sort(),
    );

    _records.add(rec);
    await AnswerHistory.instance.add(rec);

    debugPrint(
      '[log] [MOCK] saved record: diff=${rec.difficulty}, domain=${rec.domain}, major=${rec.major}',
    );

    if (_finished) return;
    await goNext();
  }

  MockExamResultData buildResultData() {
    final usedSeconds =
    _totalSeconds > 0 ? (_totalSeconds - _remainingSeconds) : 0;
    final correct = _records.where((r) => r.isCorrect).length;
    final answered = _records.length;

    return MockExamResultData(
      records: List<AnswerRecord>.unmodifiable(_records),
      totalPlanned: questionCount,
      answeredCount: answered,
      correctCount: correct,
      usedSeconds: usedSeconds,
      timeLimitSeconds: _totalSeconds,
      finishedByTimeout: _finishedByTimeout,
    );
  }

  bool finishExam({required bool byTimeout}) {
    if (_finished) return false;
    _finished = true;
    _finishedByTimeout = byTimeout;
    _timer?.cancel();
    notifyListeners();
    return true;
  }

  Future<MockExamPrefetchedQuestion> _fetchQuestionForIndex(int index) async {
    final spec = MockExamPlanner.pick(
      examType: examType,
      random: _rand,
    );

    final data = await QuestionEngine.instance.generate(spec);

    return MockExamPrefetchedQuestion(
      index: index,
      difficulty: spec.difficulty,
      domain: spec.domain,
      major: spec.major,
      mid: spec.mid,
      topic: (data['meta'] as Map?)?['topic']?.toString(),
      data: data,
    );
  }

  void _kickPrefetch() {
    _prefetchController.kickPrefetch(
      currentIndex: _currentIndex,
      questionCount: questionCount,
      fetcher: _fetchQuestionForIndex,
    );
  }

  void _applyQuestion(MockExamPrefetchedQuestion q) {
    state.currentDifficulty = q.difficulty;
    state.currentDomain = q.domain;
    state.currentMajor = q.major;
    state.currentMid = q.mid;
    state.currentTopic = q.topic;

    final data = q.data;
    state.questionText = (data['question'] as String?)?.trim();

    final rawChoices = data['choices'] as Map?;
    state.choices =
        rawChoices?.map((k, v) => MapEntry(k.toString(), v.toString()));

    state.correctAnswers = (data['correctAnswers'] as List?)
        ?.map((e) => e.toString())
        .toList() ??
        [(data['correct'] ?? '').toString()];

    state.questionKind = (data['questionKind'] as String?) ?? 'single';

    state.explanation = (data['explanation'] as String?) ?? '';
    final rawRat = data['rationales'] as Map?;
    state.rationales =
        rawRat?.map((k, v) => MapEntry(k.toString(), v.toString()));

    final rawMeta = data['meta'] as Map?;
    state.meta = rawMeta?.map((k, v) => MapEntry(k.toString(), v));

    state.userAnswers = {};

    debugPrint(
      '[log] [MOCK] applied q index=${q.index} diff=${q.difficulty} '
          'domain=${q.domain} major=${q.major} mid=${q.mid ?? '(none)'}',
    );
  }
}

// lib/features/mock_exam/logic/mock_exam_planner.dart
import 'dart:math';

import '../../../data/categories.dart';
import '../../../data/hisshu_categories.dart';
import '../../../questioning/models/question_spec.dart';
import '../../../questioning/repositories/category_repository.dart';

class MockExamPlanner {
  const MockExamPlanner._();

  static QuestionSpec pick({
    required String examType,
    required Random random,
  }) {
    // mix: 3種ランダム
    // hisshu: 必修固定
    // ippan: 一般固定
    // jokyo: 状況固定
    final String difficulty;
    switch (examType) {
      case 'hisshu':
        difficulty = '必修問題';
        break;
      case 'ippan':
        difficulty = '一般問題';
        break;
      case 'jokyo':
        difficulty = '状況設定問題';
        break;
      case 'mix':
      default:
        const pool = ['必修問題', '一般問題', '状況設定問題'];
        difficulty = pool[random.nextInt(pool.length)];
        break;
    }

    if (difficulty == '必修問題') {
      final majorItems = CategoryRepository.hisshuMajorItems();
      final major = majorItems.isNotEmpty
          ? majorItems[random.nextInt(majorItems.length)]
          : '1. 健康の定義と理解';

      return QuestionSpec(
        difficulty: '必修問題',
        domain: kHisshuCategory,
        major: major,
        mid: null,
        scenarioAspectCode: null,
      );
    }

    if (difficulty == '状況設定問題') {
      final domain = _pickRandomFrom(situationalDomains, random);
      final majors = CategoryRepository.generalMajorsOf(domain);
      final major = _pickRandomFrom(majors, random);

      final midList = CategoryRepository.generalMidsOf(domain, major);
      final mid = midList.isNotEmpty ? _pickRandomFrom(midList, random) : null;

      // 観点はランダム（A..E）
      const aspectKeys = ['A', 'B', 'C', 'D', 'E'];
      final aspect = aspectKeys[random.nextInt(aspectKeys.length)];

      return QuestionSpec(
        difficulty: '状況設定問題',
        domain: domain,
        major: major,
        mid: mid,
        scenarioAspectCode: aspect,
      );
    }

    // 一般問題
    final domains = CategoryRepository.generalDomains();
    final domain = _pickRandomFrom(domains, random);

    final majors = CategoryRepository.generalMajorsOf(domain);
    final major = _pickRandomFrom(majors, random);

    final midList = CategoryRepository.generalMidsOf(domain, major);
    final mid = midList.isNotEmpty ? _pickRandomFrom(midList, random) : null;

    return QuestionSpec(
      difficulty: '一般問題',
      domain: domain,
      major: major,
      mid: mid,
      scenarioAspectCode: null,
    );
  }

  static T _pickRandomFrom<T>(List<T> list, Random random) {
    if (list.isEmpty) {
      throw StateError('カテゴリ候補が空です');
    }
    return list[random.nextInt(list.length)];
  }
}

// lib/features/mock_exam/logic/mock_exam_prefetch_controller.dart
import 'package:flutter/material.dart';

class MockExamPrefetchedQuestion {
  final int index;
  final String difficulty;
  final String domain;
  final String major;
  final String? mid;
  final String? topic;
  final Map<String, dynamic> data;

  MockExamPrefetchedQuestion({
    required this.index,
    required this.difficulty,
    required this.domain,
    required this.major,
    required this.mid,
    required this.topic,
    required this.data,
  });
}

class MockExamPrefetchController {
  MockExamPrefetchedQuestion? _prefetched;
  Future<MockExamPrefetchedQuestion>? _prefetchFuture;
  int _prefetchToken = 0;

  Future<MockExamPrefetchedQuestion>? get inFlight => _prefetchFuture;

  MockExamPrefetchedQuestion? consumeIfReady(int index) {
    if (_prefetched != null && _prefetched!.index == index) {
      final q = _prefetched!;
      _prefetched = null;
      return q;
    }
    return null;
  }

  void clearCache() {
    _prefetched = null;
    _prefetchFuture = null;
  }

  void dispose() {
    _prefetched = null;
    _prefetchFuture = null;
    _prefetchToken++;
  }

  void kickPrefetch({
    required int currentIndex,
    required int questionCount,
    required Future<MockExamPrefetchedQuestion> Function(int index) fetcher,
  }) {
    final nextIndex = currentIndex + 1;
    if (nextIndex >= questionCount) return;

    if (_prefetched != null && _prefetched!.index == nextIndex) return;

    final myToken = ++_prefetchToken;

    _prefetchFuture = fetcher(nextIndex).then((q) {
      if (myToken != _prefetchToken) return q;

      _prefetched = q;
      debugPrint(
        '[log] [MOCK] prefetched ready: index=${q.index} diff=${q.difficulty}',
      );
      return q;
    }).catchError((e) {
      debugPrint('[warn] [MOCK] prefetch failed: $e');

      if (myToken == _prefetchToken) {
        _prefetchFuture = null;
        _prefetched = null;
      }

      return Future<MockExamPrefetchedQuestion>.error(e);
    });
  }
}

