import 'package:flutter/material.dart';

import '../../../shared/widgets/base_scaffold.dart';

import '../logic/practice_question_controller.dart';
import '../widgets/practice_loading_card.dart';
import '../widgets/practice_question_controls.dart';
import '../widgets/practice_question_view.dart';

import '../../../questioning/repositories/category_repository.dart';
import '../../../data/categories.dart';

import 'practice_result_screen.dart';

// ランダム指定用の内部ID
const String kRandomDomainId = '__RANDOM_DOMAIN__';
const String kRandomMajorId = '__RANDOM_MAJOR__';

class QuestionScreen extends StatefulWidget {
  const QuestionScreen({super.key});

  @override
  State<QuestionScreen> createState() => _QuestionScreenState();
}

class _QuestionScreenState extends State<QuestionScreen> {
  final PracticeQuestionController _controller = PracticeQuestionController();

  static const String modeSituational = '状況設定問題';

  List<String> get hisshuMajorItems => CategoryRepository.hisshuMajorItems();

  static const Map<String, String> _scenarioAspects = {
    'A': 'A. 対象や家族に切れ目のない支援を提供するための継続した看護',
    'B': 'B. 複合的な状況にある対象や、複合的に提供されている看護の状況を判断し、危険を回避する取組み',
    'C': 'C. 看護の提供者が、看護場面において自身の安全を確保するための総合的な判断や対応',
    'D': 'D. 発災からの経過に応じて被災者に提供されている診療や支援を促進するための看護',
    'E': 'E. A～Dを促進するための多職種連携',
  };

  void _handleControllerChanged() {
    if (!mounted) return;
    setState(() {});
  }

  @override
  void initState() {
    super.initState();
    _controller.initialize();
    _controller.addListener(_handleControllerChanged);
  }

  @override
  void dispose() {
    _controller.removeListener(_handleControllerChanged);
    _controller.dispose();
    super.dispose();
  }

  Future<void> _generateQuestion() async {
    setState(() {
      _controller.state.isLoading = true;
      _controller.state.clearQuestion();
      _controller.clearAnswers();
      _controller.state.loadingMessageIndex = 0;
      _controller.state.loadingProgress = 0;
    });

    _controller.startLoadingUi();

    try {
      final data = await _controller.generateQuestion(
        mode: _controller.state.mode,
        selectedDomain: _controller.state.selectedDomain,
        selectedMajor: _controller.state.selectedMajor,
        selectedMid: _controller.state.selectedMid,
        useMid: _controller.state.useMid,
        hisshuMajor: _controller.state.selectedHisshuMajor,
        scenarioAspect: _controller.state.selectedScenarioAspectCode,
      );

      await _controller.completeLoadingAndWait();

      if (!mounted) return;

      setState(() {
        _controller.state.questionText =
            (data['question'] as String?)?.trim();

        final rawChoices = data['choices'] as Map?;
        _controller.state.choices =
            rawChoices?.map((k, v) => MapEntry(k.toString(), v.toString()));

        _controller.state.correctAnswers =
            (data['correctAnswers'] as List?)
                ?.map((e) => e.toString())
                .toList() ??
                [(data['correct'] ?? '').toString()];

        _controller.state.questionKind =
            (data['questionKind'] as String?) ?? 'single';

        _controller.state.explanation =
            (data['explanation'] as String?) ?? '';

        final rawRat = data['rationales'] as Map?;
        _controller.state.rationales =
            rawRat?.map((k, v) => MapEntry(k.toString(), v.toString()));

        final rawMeta = data['meta'] as Map?;
        _controller.state.meta =
            rawMeta?.map((k, v) => MapEntry(k.toString(), v));

        _controller.state.isLoading = false;
      });
    } catch (e) {
      _controller.stopLoadingUi();

      if (!mounted) return;

      setState(() {
        _controller.state.isLoading = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('問題の生成に失敗しました：$e')),
      );
    }
  }

  Future<void> _submitAnswer() async {
    if (_controller.state.questionText == null ||
        _controller.state.choices == null ||
        _controller.state.correctAnswers == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('問題を生成してから解答してください。')),
      );
      return;
    }

    if (_controller.state.userAnswers.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('選択肢を選んでください。')),
      );
      return;
    }

    try {
      await _controller.saveAnswer(
        difficulty: _controller.state.mode,
        question: _controller.state.questionText!,
        choices: _controller.state.choices!,
        correctAnswers: _controller.state.correctAnswers!,
        questionKind: _controller.state.questionKind,
        explanation: _controller.state.explanation,
        rationales: _controller.state.rationales,
        meta: _controller.state.meta,
        selectedDomain: _controller.state.selectedDomain,
        selectedMajor: _controller.state.selectedMajor,
        selectedMid: _controller.state.selectedMid,
        useMid: _controller.state.useMid,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('履歴の保存に失敗しました：$e')),
        );
      }
    }

    if (!mounted) return;

    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => ResultScreen(
          question: _controller.state.questionText!,
          choices: _controller.state.choices!,
          selectedAnswers: _controller.state.userAnswers.toList(),
          correctAnswers: _controller.state.correctAnswers!,
          explanation: _controller.state.explanation ?? '',
          rationales: _controller.state.rationales,
          onGenerateNext: _generateQuestion,
          difficulty: _controller.state.mode,
          domain: _controller.state.meta?['domain'] as String?,
          major: _controller.state.meta?['major'] as String?,
          mid: _controller.state.meta?['mid'] as String?,
          topic: _controller.state.meta?['topic'] as String?,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final domainList = _controller.state.mode == modeSituational
        ? situationalDomains
        : CategoryRepository.generalDomains();

    return BaseScaffold(
      title: '出題',
      body: SafeArea(
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              QuestionControls(
                mode: _controller.state.mode,
                onModeChanged: (val) {
                  setState(() {
                    _controller.handleModeChanged(val);
                  });
                },
                isLoading: false,
                onGeneratePressed: _generateQuestion,
                domainItems: domainList,
                selectedDomain: _controller.state.selectedDomain,
                onDomainChanged: (val) {
                  setState(() {
                    _controller.handleDomainChanged(val);
                  });
                },
                majorItems: CategoryRepository.generalMajorsOf(
                  _controller.state.selectedDomain,
                ),
                selectedMajor: _controller.state.selectedMajor,
                onMajorChanged: (val) {
                  setState(() {
                    _controller.handleMajorChanged(val);
                  });
                },
                useMid: _controller.state.useMid,
                onUseMidChanged: (v) {
                  setState(() {
                    _controller.handleUseMidChanged(v);
                  });
                },
                midItems: CategoryRepository.generalMidsOf(
                  _controller.state.selectedDomain,
                  _controller.state.selectedMajor,
                ),
                selectedMid: _controller.state.selectedMid,
                onMidChanged: (val) {
                  setState(() {
                    _controller.handleMidChanged(val);
                  });
                },
                hisshuMajorItems: hisshuMajorItems,
                selectedHisshuMajor: _controller.state.selectedHisshuMajor,
                onHisshuMajorChanged: (val) {
                  setState(() {
                    _controller.handleHisshuMajorChanged(val);
                  });
                },
                scenarioAspects: _scenarioAspects,
                selectedScenarioAspectCode:
                _controller.state.selectedScenarioAspectCode,
                onScenarioAspectChanged: (val) {
                  setState(() {
                    _controller.handleScenarioAspectChanged(val);
                  });
                },
              ),
              const SizedBox(height: 16),
              if (_controller.state.isLoading)
                PracticeLoadingCard(
                  message: PracticeQuestionController.loadingMessages[
                  _controller.state.loadingMessageIndex.clamp(
                    0,
                    PracticeQuestionController.loadingMessages.length - 1,
                  )],
                  progress: _controller.state.loadingProgress,
                ),
              if (_controller.state.questionText != null &&
                  _controller.state.choices != null)
                PracticeQuestionView(
                  questionText: _controller.state.questionText!,
                  choices: _controller.state.choices!,
                  questionKind: _controller.state.questionKind,
                  selectedAnswers: _controller.state.userAnswers.toList(),
                  onSelectSingle: (val) {
                    _controller.selectSingle(val);
                    setState(() {});
                  },
                  onToggleMultiple: (val) {
                    _controller.toggleMultiple(val);
                    setState(() {});
                  },
                  onSubmit: _submitAnswer,
                ),
            ],
          ),
        ),
      ),
    );
  }
}

// lib/features/practice/screens/practice_result_screen.dart

import 'dart:math';

import 'package:confetti/confetti.dart';
import 'package:flutter/material.dart';

import '../../../shared/widgets/base_scaffold.dart';
import '../../../shared/widgets/app_buttons.dart';
import '../utils/practice_result_formatter.dart';
import '../widgets/practice_result_block.dart';

class ResultScreen extends StatefulWidget {
  final String question;
  final Map<String, String> choices;

  /// 複数対応（単一の場合も1要素で渡る）
  final List<String> selectedAnswers;
  final List<String> correctAnswers;

  final String explanation;
  final Map<String, String>? rationales;

  /// 次の問題を生成（QuestionScreen 側から渡される）
  final VoidCallback onGenerateNext;

  /// メタ（任意）
  final String? difficulty;
  final String? domain;
  final String? major;
  final String? mid;
  final String? topic;

  /// 問題タイプ（'single' | 'multiple' | 'select_incorrect'）
  /// 渡されない場合は 'single' として扱う（後方互換）
  final String? questionKind;

  const ResultScreen({
    super.key,
    required this.question,
    required this.choices,
    required this.selectedAnswers,
    required this.correctAnswers,
    required this.explanation,
    this.rationales,
    required this.onGenerateNext,
    this.difficulty,
    this.domain,
    this.major,
    this.mid,
    this.topic,
    this.questionKind,
  });

  @override
  State<ResultScreen> createState() => _ResultScreenState();
}

class _ResultScreenState extends State<ResultScreen> {
  bool _showOverlay = false;
  bool _isCorrect = false;

  late final ConfettiController _leftConfettiController;
  late final ConfettiController _rightConfettiController;

  @override
  void initState() {
    super.initState();

    _leftConfettiController = ConfettiController(
      duration: const Duration(milliseconds: 1200),
    );
    _rightConfettiController = ConfettiController(
      duration: const Duration(milliseconds: 1200),
    );

    _isCorrect = _isFullyCorrect();
    _showOverlay = true;

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_isCorrect) {
        _leftConfettiController.play();
        _rightConfettiController.play();
      }
      _scheduleOverlayHide();
    });
  }

  @override
  void dispose() {
    _leftConfettiController.dispose();
    _rightConfettiController.dispose();
    super.dispose();
  }

  /// 完全一致方式の正誤判定
  bool _isFullyCorrect() {
    final sel = widget.selectedAnswers.toSet();
    final cor = widget.correctAnswers.toSet();

    if (sel.isEmpty || cor.isEmpty) return false;
    if (sel.length != cor.length) return false;
    return sel.containsAll(cor);
  }

  void _scheduleOverlayHide() async {
    await Future.delayed(const Duration(milliseconds: 900));
    if (!mounted) return;

    setState(() {
      _showOverlay = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final kind = widget.questionKind ?? 'single';

    final normalizedExplanation = PracticeResultFormatter.normalizeExplanation(
      explanation: widget.explanation,
      correctAnswers: widget.correctAnswers,
      questionKind: kind,
    );

    return Stack(
      children: [
        BaseScaffold(
          title: '解答結果',
          body: SafeArea(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  ResultBlock(
                    question: widget.question,
                    choices: widget.choices,
                    selectedAnswers: widget.selectedAnswers,
                    correctAnswers: widget.correctAnswers,
                    explanation: normalizedExplanation,
                    rationales: widget.rationales,
                    questionKind: kind,
                  ),
                  const SizedBox(height: 20),
                  SizedBox(
                    width: double.infinity,
                    child: AppButtons.success(
                      label: '次の問題を生成',
                      icon: Icons.refresh,
                      onPressed: () {
                        widget.onGenerateNext();
                        Navigator.of(context).pop();
                      },
                    ),
                  ),
                  const SizedBox(height: 10),
                  SizedBox(
                    width: double.infinity,
                    child: AppButtons.primary(
                      label: '出題に戻る',
                      icon: Icons.arrow_back,
                      onPressed: () => Navigator.of(context).pop(),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),

        _buildResultOverlay(context),
        if (_isCorrect) _buildConfettiLayer(),
      ],
    );
  }

  Widget _buildConfettiLayer() {
    return IgnorePointer(
      child: Stack(
        children: [
          // 左側クラッカー
          Align(
            alignment: const Alignment(-0.6, -0.15), // ← 発射位置を上げる
            child: ConfettiWidget(
              confettiController: _leftConfettiController,
              blastDirection: -pi / 4, // 右上
              emissionFrequency: 0.01,
              numberOfParticles: 30, // ← 粒増やす
              maxBlastForce: 45, // ← 強く吹き出す
              minBlastForce: 28,
              gravity: 0.45, // ← 落ちる感じ強化
              shouldLoop: false,
              blastDirectionality: BlastDirectionality.directional,
            ),
          ),

          // 右側クラッカー
          Align(
            alignment: const Alignment(0.6, -0.15), // ← 発射位置を上げる
            child: ConfettiWidget(
              confettiController: _rightConfettiController,
              blastDirection: -3 * pi / 4, // 左上
              emissionFrequency: 0.01,
              numberOfParticles: 30,
              maxBlastForce: 45,
              minBlastForce: 28,
              gravity: 0.45,
              shouldLoop: false,
              blastDirectionality: BlastDirectionality.directional,
            ),
          ),
        ],
      ),
    );
  }

  /// 正解 / 不正解 を大きく表示するオーバーレイ
  Widget _buildResultOverlay(BuildContext context) {
    final theme = Theme.of(context);
    final color = _isCorrect ? Colors.green.shade600 : Colors.red.shade600;
    final symbol = _isCorrect ? '◯' : '✕';
    final label = _isCorrect ? '正解！' : '不正解';

    return IgnorePointer(
      child: AnimatedOpacity(
        opacity: _showOverlay ? 1.0 : 0.0,
        duration: const Duration(milliseconds: 600),
        child: Container(
          color: Colors.black.withOpacity(0.10),
          alignment: Alignment.center,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              RichText(
                textHeightBehavior: const TextHeightBehavior(
                  applyHeightToFirstAscent: false,
                  applyHeightToLastDescent: false,
                ),
                text: TextSpan(
                  text: symbol,
                  style: TextStyle(
                    fontSize: 130,
                    fontWeight: FontWeight.w900,
                    height: 0.8,
                    color: color,
                  ),
                ),
              ),
              const SizedBox(height: 8),
              Text(
                label,
                textAlign: TextAlign.center,
                style: theme.textTheme.headlineMedium?.copyWith(
                  fontWeight: FontWeight.w900,
                  color: color,
                  height: 1.0,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// lib/features/practice/utils/practice_result_formatter.dart

class PracticeResultFormatter {
  const PracticeResultFormatter._();

  /// explanation の整形
  ///
  /// - select_incorrect のときだけ、
  ///   「選択肢CとDが誤った記述です。」などの一文を先頭に挿入（または置換）して
  ///   correctAnswers と必ず整合するようにする。
  static String normalizeExplanation({
    required String explanation,
    required List<String> correctAnswers,
    required String questionKind,
  }) {
    final trimmed = explanation.trim();
    if (trimmed.isEmpty) return '';

    if (questionKind != 'select_incorrect') {
      return trimmed;
    }

    final labels = correctAnswers
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toSet()
        .toList()
      ..sort();

    if (labels.isEmpty) return trimmed;

    final joined = labelsToJoined(labels);
    final head = '選択肢$joinedが誤った記述です。';

    final firstPeriodIndex = trimmed.indexOf('。');
    if (firstPeriodIndex >= 0) {
      final firstSentence = trimmed.substring(0, firstPeriodIndex + 1);
      final rest = trimmed.substring(firstPeriodIndex + 1).trimLeft();

      final isIncorrectLeadSentence =
          firstSentence.contains('選択肢') &&
              (firstSentence.contains('誤った') ||
                  firstSentence.contains('誤り') ||
                  firstSentence.contains('誤っている'));

      if (isIncorrectLeadSentence) {
        return rest.isEmpty ? head : '$head$rest';
      }

      return '$head$trimmed';
    }

    return '$head$trimmed';
  }

  /// ラベル配列を「A」「AとB」「A、BとC」形式に連結
  static String labelsToJoined(List<String> labels) {
    if (labels.isEmpty) return '';
    if (labels.length == 1) return labels.first;
    if (labels.length == 2) return '${labels[0]}と${labels[1]}';

    final head = labels.sublist(0, labels.length - 1).join('、');
    return '$headと${labels.last}';
  }
}

