import 'package:flutter/material.dart';

import '../../../shared/widgets/choice_tile.dart';
import '../../../shared/widgets/explanation_block.dart';

/// 解答結果の表示ブロック
/// - 問題文/解説・根拠は ExplanationBlock で統一
/// - 正答0件でもUIが崩れないようガード
class ResultBlock extends StatelessWidget {
  const ResultBlock({
    super.key,
    required this.question,
    required this.choices,            // Map<'A'..'E', text>
    required this.selectedAnswers,    // List<'A'..'E'>
    required this.correctAnswers,     // List<'A'..'E'>
    required this.explanation,
    this.rationales,                  // Map<label, text>?
    this.questionKind,                // 'single' | 'multiple' | 'select_incorrect'（任意）
  });

  final String question;
  final Map<String, String> choices;
  final List<String> selectedAnswers;
  final List<String> correctAnswers;
  final String explanation;
  final Map<String, String>? rationales;
  final String? questionKind;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    // 表示順は A..E の昇順に統一
    final orderedKeys = ['A', 'B', 'C', 'D', 'E'].where(choices.containsKey).toList();

    final sel = selectedAnswers.toSet();
    final cor = correctAnswers.toSet();

    final isIncorrect = (questionKind ?? '').contains('incorrect');
    final correctCount = cor.length;

    // ===== 正答が0件でも落ちないようフォールバック表示 =====
    if (correctCount == 0) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          ExplanationBlock(title: '問題', body: question),
          const SizedBox(height: 20),

          Text('選択肢', style: theme.textTheme.titleMedium),
          const SizedBox(height: 8),
          ...orderedKeys.map((label) {
            final text = choices[label] ?? '';
            final userSelected = sel.contains(label);

            final state = userSelected ? ChoiceTileState.incorrect : ChoiceTileState.normal;
            return Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: ChoiceTile(
                label: label,
                text: text,
                state: state,
                dense: true,
              ),
            );
          }),

          const SizedBox(height: 20),
          Text('解答：該当なし', style: theme.textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.w600)),

          const SizedBox(height: 8),
          if (explanation.trim().isNotEmpty)
            ExplanationBlock(title: '解説', body: explanation.trim()),
        ],
      );
    }

    // ===== 通常表示 =====
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // 問題
        ExplanationBlock(
          title: '問題',
          body: question,
        ),
        const SizedBox(height: 20),

        // 選択肢
        Text('選択肢', style: theme.textTheme.titleMedium),
        const SizedBox(height: 8),
        ...orderedKeys.map((label) {
          final text = choices[label] ?? '';
          final userSelected = sel.contains(label);
          final isCorrect = cor.contains(label);

          ChoiceTileState state = ChoiceTileState.normal;
          if (userSelected && isCorrect) {
            state = ChoiceTileState.correct;
          } else if (userSelected && !isCorrect) {
            state = ChoiceTileState.incorrect;
          } else if (!userSelected && isCorrect) {
            state = ChoiceTileState.correct;
          }

          return Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: ChoiceTile(
              label: label,
              text: text,
              state: state,
              dense: true,
            ),
          );
        }),

        const SizedBox(height: 20),

        // 解答の一文
        _answerLine(context, isIncorrect, correctCount, cor),

        const SizedBox(height: 8),

        // 解説
        if (explanation.trim().isNotEmpty) ...[
          ExplanationBlock(
            title: '解説',
            body: explanation.trim(),
          ),
          const SizedBox(height: 20),
        ],

        // 根拠
        if (rationales != null && rationales!.isNotEmpty) ...[
          Text('根拠', style: theme.textTheme.titleMedium),
          const SizedBox(height: 8),
          ..._rationaleTiles(orderedKeys, cor),
        ],
      ],
    );
  }

  /// 「解答：A と D（2つ）」の行
  Widget _answerLine(BuildContext context, bool isIncorrect, int count, Set<String> cor) {
    final theme = Theme.of(context);
    final list = _labelsToJoined(cor.toList()..sort());
    final suffix = count >= 2 ? '（${count}つ）' : '';
    final head = isIncorrect ? '解答（誤っているもの）' : '解答';
    return Text(
      '$head：$list$suffix',
      style: theme.textTheme.bodyLarge?.copyWith(fontWeight: FontWeight.w600),
    );
  }

  /// 根拠のタイル群（ChoiceTile で正誤色を合わせる）
  List<Widget> _rationaleTiles(List<String> orderedKeys, Set<String> cor) {
    final items = <Widget>[];
    for (final k in orderedKeys) {
      final txt = rationales?[k]?.trim() ?? '';
      if (txt.isEmpty) continue;
      final isCorrect = cor.contains(k);
      items.add(
        Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: ChoiceTile(
            label: k,
            text: txt,
            state: isCorrect ? ChoiceTileState.correct : ChoiceTileState.incorrect,
            dense: true,
          ),
        ),
      );
    }
    return items;
  }

  /// ['A','C','D'] -> 'A と C と D'
  String _labelsToJoined(List<String> labels) {
    if (labels.isEmpty) return '';
    if (labels.length == 1) return labels.first;
    return [
      ...labels.sublist(0, labels.length - 1).map((e) => e),
      'と ${labels.last}'
    ].join(' ');
  }
}

// lib/features/score/screens/score_screen.dart

import 'package:flutter/material.dart';

import '../../history/services/history_answer_service.dart';
import '../../../shared/widgets/base_scaffold.dart';
import '../widgets/score_history_charts.dart';
import '../widgets/score_summary_card.dart';

class ScoreScreen extends StatefulWidget {
  const ScoreScreen({super.key});

  @override
  State<ScoreScreen> createState() => _ScoreScreenState();
}

class _ScoreScreenState extends State<ScoreScreen>
    with SingleTickerProviderStateMixin {
  late Future<List<AnswerRecord>> _future;

  String _filter = 'すべて';

  late final AnimationController _animController;
  late final Animation<Offset> _slideAnim;

  @override
  void initState() {
    super.initState();
    _future = AnswerHistory.instance.all();

    _animController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 500),
    );
    _slideAnim = Tween<Offset>(
      begin: const Offset(0, 0.05),
      end: Offset.zero,
    ).animate(
      CurvedAnimation(
        parent: _animController,
        curve: Curves.easeOutCubic,
      ),
    );
    _animController.forward();
  }

  @override
  void dispose() {
    _animController.dispose();
    super.dispose();
  }

  Future<void> _reload() async {
    setState(() {
      _future = AnswerHistory.instance.all();
    });
    await _future;
  }

  List<AnswerRecord> _applyFilter(List<AnswerRecord> items) {
    final now = DateTime.now();

    switch (_filter) {
      case '直近1週間':
        final from7 = now.subtract(const Duration(days: 7));
        return items.where((r) => r.ts.isAfter(from7)).toList();

      case '直近1ヶ月':
        final from30 = now.subtract(const Duration(days: 30));
        return items.where((r) => r.ts.isAfter(from30)).toList();

      default:
        return items;
    }
  }

  String _domainLabel(String? domain) {
    if (domain == null || domain.isEmpty) {
      return '未指定';
    }
    return domain;
  }

  void _incrementStatMap(
      Map<String, Map<String, int>> target,
      String key,
      bool isCorrect,
      ) {
    target.putIfAbsent(key, () => {'total': 0, 'correct': 0});
    target[key]!['total'] = (target[key]!['total'] ?? 0) + 1;

    if (isCorrect) {
      target[key]!['correct'] = (target[key]!['correct'] ?? 0) + 1;
    }
  }

  void _incrementNestedStatMap(
      Map<String, Map<String, Map<String, int>>> target,
      String difficulty,
      String domain,
      bool isCorrect,
      ) {
    target.putIfAbsent(difficulty, () => <String, Map<String, int>>{});
    target[difficulty]!
        .putIfAbsent(domain, () => {'total': 0, 'correct': 0});

    target[difficulty]![domain]!['total'] =
        (target[difficulty]![domain]!['total'] ?? 0) + 1;

    if (isCorrect) {
      target[difficulty]![domain]!['correct'] =
          (target[difficulty]![domain]!['correct'] ?? 0) + 1;
    }
  }

  @override
  Widget build(BuildContext context) {
    return BaseScaffold(
      title: '成績',
      body: FutureBuilder<List<AnswerRecord>>(
        future: _future,
        builder: (context, snap) {
          if (snap.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (snap.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Text('読み込みに失敗しました: ${snap.error}'),
              ),
            );
          }

          final allItems = snap.data ?? const <AnswerRecord>[];

          // AI学習成績のみを対象（過去問はスコア画面では扱わない）
          final trainingItems =
          allItems.where((r) => r.sourceType != 'past_exam').toList();

          final filteredTraining = _applyFilter(trainingItems);

          return RefreshIndicator(
            onRefresh: _reload,
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
              children: [
                _buildFilterDropdown(),
                const SizedBox(height: 16),
                if (filteredTraining.isEmpty)
                  const Padding(
                    padding: EdgeInsets.only(top: 40),
                    child: Center(
                      child: Text('該当する解答履歴がありません'),
                    ),
                  )
                else
                  _buildTrainingContent(filteredTraining),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _buildTrainingContent(List<AnswerRecord> items) {
    final theme = Theme.of(context);

    final total = items.length;
    final correct = items.where((r) => r.isCorrect).length;
    final rate = total == 0 ? 0.0 : (correct / total);

    // 出題形式別
    final byDifficulty = <String, Map<String, int>>{};
    for (final record in items) {
      _incrementStatMap(
        byDifficulty,
        record.difficulty,
        record.isCorrect,
      );
    }

    // 分野別
    final byDomain = <String, Map<String, int>>{};
    for (final record in items) {
      _incrementStatMap(
        byDomain,
        _domainLabel(record.domain),
        record.isCorrect,
      );
    }

    // 出題形式 × 分野
    final byDifficultyDomain = <String, Map<String, Map<String, int>>>{};
    for (final record in items) {
      _incrementNestedStatMap(
        byDifficultyDomain,
        record.difficulty,
        _domainLabel(record.domain),
        record.isCorrect,
      );
    }

    const diffOrder = ['必修問題', '一般問題', '状況設定問題'];
    final diffKeys = [
      ...diffOrder.where((k) => byDifficultyDomain.containsKey(k)),
      ...byDifficultyDomain.keys.where((k) => !diffOrder.contains(k)).toList()
        ..sort(),
    ];

    final totalStat = _StatCard(
      title: '総合成績',
      lines: [
        '解答数：$total',
        '正解数：$correct',
        '正答率：${(rate * 100).toStringAsFixed(1)}%',
      ],
    );

    final diffLines = byDifficulty.entries.map((entry) {
      final t = entry.value['total'] ?? 0;
      final c = entry.value['correct'] ?? 0;
      final r = t == 0 ? 0.0 : c / t;
      return '${entry.key}：$c / $t（${(r * 100).toStringAsFixed(1)}%）';
    }).toList();

    final diffStat = _StatCard(
      title: '出題形式別',
      lines: diffLines,
    );

    final topRow = LayoutBuilder(
      builder: (context, constraints) {
        final isNarrow = constraints.maxWidth < 420;

        if (isNarrow) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              SizedBox(width: double.infinity, child: totalStat),
              const SizedBox(height: 12),
              SizedBox(width: double.infinity, child: diffStat),
            ],
          );
        }

        return Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(child: totalStat),
            const SizedBox(width: 16),
            Expanded(child: diffStat),
          ],
        );
      },
    );

    final trendCard = _buildTrendCard(items);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        ScoreSummaryCard(records: items),
        const SizedBox(height: 16),

        FadeTransition(
          opacity: _animController,
          child: SlideTransition(
            position: _slideAnim,
            child: topRow,
          ),
        ),
        const SizedBox(height: 16),

        if (trendCard != null) ...[
          FadeTransition(
            opacity: _animController,
            child: SlideTransition(
              position: _slideAnim,
              child: trendCard,
            ),
          ),
          const SizedBox(height: 24),
        ] else
          const SizedBox(height: 24),

        Text(
          '分野別成績',
          style: theme.textTheme.titleMedium,
        ),
        const SizedBox(height: 8),
        _expansionCard(
          title: '正答率（分野別）',
          child: MiniBarChart(
            title: null,
            items: buildBarItemsFromStatMap(byDomain),
            barHeight: 20,
            maxItems: 10,
          ),
        ),

        const SizedBox(height: 16),

        Text(
          '出題形式 × 分野',
          style: theme.textTheme.titleMedium,
        ),
        const SizedBox(height: 8),
        _expansionCard(
          title: '出題形式ごとの分野別正答率',
          child: Column(
            children: diffKeys.map((diff) {
              final domainStats =
                  byDifficultyDomain[diff] ?? const <String, Map<String, int>>{};

              if (domainStats.isEmpty) {
                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 6),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text('$diff：データなし'),
                  ),
                );
              }

              return Padding(
                padding: const EdgeInsets.only(bottom: 12),
                child: MiniBarChart(
                  title: '$diff の分野別正答率',
                  items: buildBarItemsFromStatMap(domainStats),
                  barHeight: 18,
                  maxItems: 8,
                ),
              );
            }).toList(),
          ),
        ),
      ],
    );
  }

  Widget? _buildTrendCard(List<AnswerRecord> items) {
    if (items.isEmpty) return null;

    final buckets = <DateTime, _TrendBucket>{};

    for (final record in items) {
      final day = DateTime(record.ts.year, record.ts.month, record.ts.day);
      final bucket = buckets.putIfAbsent(day, () => _TrendBucket());
      bucket.total++;
      if (record.isCorrect) {
        bucket.correct++;
      }
    }

    var keys = buckets.keys.toList()..sort();

    const maxDays = 10;
    if (keys.length > maxDays) {
      keys = keys.sublist(keys.length - maxDays);
    }

    final points = <_TrendPoint>[];
    for (final day in keys) {
      final bucket = buckets[day]!;
      final accuracy = bucket.total == 0 ? 0.0 : bucket.correct / bucket.total;
      final label = '${day.month}/${day.day}';

      points.add(
        _TrendPoint(
          label: label,
          accuracy: accuracy,
        ),
      );
    }

    if (points.isEmpty) return null;

    final theme = Theme.of(context);
    final cs = theme.colorScheme;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: cs.outlineVariant.withOpacity(0.6),
        ),
        boxShadow: const [
          BoxShadow(
            color: Colors.black12,
            blurRadius: 4,
            offset: Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '正答率の推移（直近${points.length}日）',
            style: theme.textTheme.titleMedium,
          ),
          const SizedBox(height: 12),
          SizedBox(
            height: 120,
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: points.map((point) {
                final value = point.accuracy.clamp(0.0, 1.0);
                final heightFactor = value == 0 ? 0.05 : value;

                return Expanded(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 4),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        Expanded(
                          child: Align(
                            alignment: Alignment.bottomCenter,
                            child: FractionallySizedBox(
                              heightFactor: heightFactor,
                              alignment: Alignment.bottomCenter,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: cs.primary.withOpacity(0.85),
                                  borderRadius: BorderRadius.circular(6),
                                ),
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          point.label,
                          style: theme.textTheme.bodySmall?.copyWith(
                            fontSize: 10,
                          ),
                        ),
                        Text(
                          '${(point.accuracy * 100).toStringAsFixed(0)}%',
                          style: theme.textTheme.bodySmall?.copyWith(
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }).toList(),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildFilterDropdown() {
    return Row(
      children: [
        const Text('表示期間: '),
        const SizedBox(width: 8),
        DropdownButton<String>(
          value: _filter,
          items: const [
            DropdownMenuItem(
              value: 'すべて',
              child: Text('すべて'),
            ),
            DropdownMenuItem(
              value: '直近1週間',
              child: Text('直近1週間'),
            ),
            DropdownMenuItem(
              value: '直近1ヶ月',
              child: Text('直近1ヶ月'),
            ),
          ],
          onChanged: (val) {
            if (val != null) {
              setState(() => _filter = val);
            }
          },
        ),
      ],
    );
  }

  Widget _expansionCard({
    required String title,
    required Widget child,
  }) {
    final theme = Theme.of(context);
    final cs = theme.colorScheme;

    return Container(
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: cs.outlineVariant.withOpacity(0.6),
        ),
        boxShadow: const [
          BoxShadow(
            color: Colors.black12,
            blurRadius: 4,
            offset: Offset(0, 2),
          ),
        ],
      ),
      child: Theme(
        data: theme.copyWith(
          dividerColor: Colors.transparent,
          splashColor: Colors.transparent,
          highlightColor: Colors.transparent,
        ),
        child: ExpansionTile(
          tilePadding: const EdgeInsets.symmetric(horizontal: 16),
          childrenPadding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
          title: Text(
            title,
            style: const TextStyle(fontWeight: FontWeight.bold),
          ),
          initiallyExpanded: false,
          children: [
            const SizedBox(height: 8),
            child,
          ],
        ),
      ),
    );
  }
}

class _StatCard extends StatelessWidget {
  const _StatCard({
    required this.title,
    required this.lines,
  });

  final String title;
  final List<String> lines;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final cs = theme.colorScheme;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: cs.outlineVariant.withOpacity(0.6),
        ),
        boxShadow: const [
          BoxShadow(
            color: Colors.black12,
            blurRadius: 4,
            offset: Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: theme.textTheme.titleMedium),
          const SizedBox(height: 8),
          ...lines.map((line) => Text(line)),
        ],
      ),
    );
  }
}

class _TrendBucket {
  int total = 0;
  int correct = 0;
}

class _TrendPoint {
  final String label;
  final double accuracy;

  const _TrendPoint({
    required this.label,
    required this.accuracy,
  });
}

// lib/features/score/services/score_exam_service.dart

import '../../history/services/history_answer_service.dart';

/// 国試の大きな区分
///
/// - 必修
/// - 一般
/// - 状況設定
enum ExamSection {
  hisshu,
  ippan,
  jokyo,
}

/// 国試スコアの集計結果
class ExamScore {
  final int answeredHisshu;
  final int correctHisshu;

  /// 一般 + 状況設定 をまとめた数
  final int answeredGeneralLike;
  final int correctGeneralLike;

  /// 必修正答率 (0.0〜1.0)
  final double hisshuRate;

  /// 一般＋状況設定 正答率 (0.0〜1.0)
  final double generalRate;

  /// 必修スコア（0〜50点にスケーリング）
  final double hisshuScore;

  /// 一般+状況設定スコア（0〜350点にスケーリング）
  final double generalScore;

  /// 必修合格ライン（8割以上）
  final bool isPassHisshu;

  /// 一般+状況 合格ライン（6割以上想定）
  final bool isPassGeneral;

  /// データが「そこそこ十分にある」と言えるかの目安
  final bool hasEnoughData;

  const ExamScore({
    required this.answeredHisshu,
    required this.correctHisshu,
    required this.answeredGeneralLike,
    required this.correctGeneralLike,
    required this.hisshuRate,
    required this.generalRate,
    required this.hisshuScore,
    required this.generalScore,
    required this.isPassHisshu,
    required this.isPassGeneral,
    required this.hasEnoughData,
  });

  /// 合計スコア（0〜400点）
  double get totalScore => hisshuScore + generalScore;

  /// 両方クリアしているか
  bool get isPass => isPassHisshu && isPassGeneral;
}

/// 国試スコア計算サービス
class ExamScoreService {
  ExamScoreService._();

  /// AnswerRecord から difficulty を見て区分を推定する
  static ExamSection? sectionOfRecord(AnswerRecord record) {
    final difficulty = record.difficulty.trim();

    if (difficulty.contains('必修')) {
      return ExamSection.hisshu;
    }
    if (difficulty.contains('状況')) {
      return ExamSection.jokyo;
    }
    if (difficulty.contains('一般')) {
      return ExamSection.ippan;
    }

    return null;
  }

  /// 解答履歴一覧から国試スコアを集計する
  ///
  /// スコアの考え方:
  /// - 必修：正答率 × 50点
  /// - 一般+状況：正答率 × 350点
  ///
  /// つまり
  /// 「今の正答率のまま本番を解いたと仮定したときの目安スコア」
  /// を返す。
  static ExamScore calculate(List<AnswerRecord> records) {
    int answeredHisshu = 0;
    int correctHisshu = 0;

    int answeredGeneralLike = 0;
    int correctGeneralLike = 0;

    for (final record in records) {
      final section = sectionOfRecord(record);
      if (section == null) continue;

      switch (section) {
        case ExamSection.hisshu:
          answeredHisshu++;
          if (record.isCorrect) {
            correctHisshu++;
          }
          break;

        case ExamSection.ippan:
        case ExamSection.jokyo:
          answeredGeneralLike++;
          if (record.isCorrect) {
            correctGeneralLike++;
          }
          break;
      }
    }

    final hisshuRate = _rate(correctHisshu, answeredHisshu);
    final generalRate = _rate(correctGeneralLike, answeredGeneralLike);

    final hisshuScore = hisshuRate * 50.0;
    final generalScore = generalRate * 350.0;

    final isPassHisshu = hisshuRate >= 0.8;
    final isPassGeneral = generalRate >= 0.6;

    final hasEnoughData =
        answeredHisshu >= 10 && answeredGeneralLike >= 30;

    return ExamScore(
      answeredHisshu: answeredHisshu,
      correctHisshu: correctHisshu,
      answeredGeneralLike: answeredGeneralLike,
      correctGeneralLike: correctGeneralLike,
      hisshuRate: hisshuRate,
      generalRate: generalRate,
      hisshuScore: hisshuScore,
      generalScore: generalScore,
      isPassHisshu: isPassHisshu,
      isPassGeneral: isPassGeneral,
      hasEnoughData: hasEnoughData,
    );
  }

  static double _rate(int correct, int total) {
    if (total == 0) {
      return 0.0;
    }
    return correct / total;
  }
}

// lib/features/score/services/score_history_stats.dart
import 'package:collection/collection.dart';
import '../../history/models/history_models.dart';

/// 履歴（HistoryRecordのリスト）から、グラフに必要な統計値を計算する純ロジック。
/// UIやストレージから独立しているため、テストもしやすい構成です。
class HistoryStats {
  /// 日別要約（accuracyは DailySummary.accuracy で参照）
  static List<DailySummary> dailySummaries(List<HistoryRecord> all) {
    if (all.isEmpty) return const [];

    // 日付キー（ローカル日付の 00:00）でグルーピング
    final groups = groupBy<HistoryRecord, DateTime>(
      all,
          (r) => DateTime(r.timestamp.year, r.timestamp.month, r.timestamp.day),
    );

    final out = <DailySummary>[];
    for (final entry in groups.entries) {
      final date = entry.key;
      final records = entry.value;
      final total = records.length;
      final correct = records.where((r) => r.correct).length;
      out.add(DailySummary(date: date, total: total, correct: correct));
    }

    out.sort((a, b) => a.date.compareTo(b.date));
    return out;
  }

  /// ドメイン別要約（accuracyは DomainSummary.accuracy で参照）
  static List<DomainSummary> domainSummaries(List<HistoryRecord> all) {
    if (all.isEmpty) return const [];

    final groups = groupBy<HistoryRecord, String>(all, (r) => r.domain);
    final out = <DomainSummary>[];

    for (final entry in groups.entries) {
      final domain = entry.key;
      final records = entry.value;
      final total = records.length;
      final correct = records.where((r) => r.correct).length;
      out.add(DomainSummary(domain: domain, total: total, correct: correct));
    }

    out.sort((a, b) => a.domain.compareTo(b.domain));
    return out;
  }

  /// 移動平均精度（windowDays 日のローリング）
  /// 例：windowDays=7 → 各日について直近7日間の正答率を算出
  static List<RollingPoint> rollingAccuracyByDay(
      List<HistoryRecord> all, {
        int windowDays = 7,
      }) {
    final daily = dailySummaries(all);
    if (daily.isEmpty) return const [];

    final out = <RollingPoint>[];

    for (var i = 0; i < daily.length; i++) {
      final end = daily[i].date;
      final start = end.subtract(Duration(days: windowDays - 1));
      int total = 0;
      int correct = 0;

      for (var j = 0; j <= i; j++) {
        final d = daily[j];
        if (d.date.isBefore(start) || d.date.isAfter(end)) continue;
        total += d.total;
        correct += d.correct;
      }

      final acc = total == 0 ? 0.0 : correct / total;
      out.add(RollingPoint(date: end, accuracy: acc));
    }
    return out;
  }

  /// 直近N問の正答率（質問数ベースの移動窓）
  static double recentAccuracy(List<HistoryRecord> all, {int lastN = 20}) {
    if (all.isEmpty) return 0.0;
    final slice = (all.length <= lastN) ? all : all.sublist(all.length - lastN);
    final total = slice.length;
    final correct = slice.where((r) => r.correct).length;
    return total == 0 ? 0.0 : correct / total;
  }

  /// 正解・不正解の連続記録
  static Streaks streaks(List<HistoryRecord> all) {
    int currentCorrect = 0, bestCorrect = 0;
    int currentWrong = 0, bestWrong = 0;

    for (final r in all) {
      if (r.correct) {
        currentCorrect += 1;
        bestCorrect = currentCorrect > bestCorrect ? currentCorrect : bestCorrect;
        currentWrong = 0;
      } else {
        currentWrong += 1;
        bestWrong = currentWrong > bestWrong ? currentWrong : bestWrong;
        currentCorrect = 0;
      }
    }

    return Streaks(
      currentCorrect: currentCorrect,
      bestCorrect: bestCorrect,
      currentWrong: currentWrong,
      bestWrong: bestWrong,
    );
  }

  /// 指定ドメイン/大項目でフィルタ。UI側のドロップダウンと組み合わせやすい。
  static List<HistoryRecord> filter({
    required List<HistoryRecord> all,
    String? domain,
    String? major,
    String? mid,
  }) {
    return all.where((r) {
      if (domain != null && domain.isNotEmpty && r.domain != domain) return false;
      if (major != null && major.isNotEmpty && r.major != major) return false;
      if (mid != null && mid.isNotEmpty && r.mid != mid) return false;
      return true;
    }).toList();
  }
}

// lib/features/score/widgets/score_chart_panel.dart
import 'package:flutter/material.dart';

import '../../history/services/history_answer_service.dart';
import '../../history/models/history_models.dart';
import '../services/score_history_stats.dart';
import 'score_history_charts.dart';

/// 成績画面などに配置できる、分野別正答率の棒グラフパネル。
///
/// 画面側は `const ScoreChartPanel()` を配置するだけで使える。
/// 内部で解答履歴を読み込み、HistoryRecord へ最小変換したうえで
/// 分野別統計を作成し、MiniBarChart に渡して表示する。
class ScoreChartPanel extends StatelessWidget {
  final String title;
  final int maxItems;

  const ScoreChartPanel({
    super.key,
    this.title = '分野別の正答率',
    this.maxItems = 6,
  });

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<AnswerRecord>>(
      future: AnswerHistory.instance.all(),
      builder: (context, snap) {
        if (!snap.hasData || snap.data!.isEmpty) {
          return const SizedBox.shrink();
        }

        final answers = snap.data!;

        // AnswerRecord → HistoryRecord へ最小情報で変換
        final records = answers.map((r) {
          return HistoryRecord(
            timestamp: r.ts,
            difficulty: r.difficulty,
            domain: r.domain ?? '未指定',
            major: '',
            mid: null,
            topic: null,
            correct: r.isCorrect,
            elapsedMs: null,
          );
        }).toList();

        // 分野別に要約 → MiniBarChart アイテムへ
        final summaries = HistoryStats.domainSummaries(records);
        if (summaries.isEmpty) {
          return const SizedBox.shrink();
        }

        final items = buildBarItemsFromDomainSummaries(summaries);

        return Padding(
          padding: const EdgeInsets.only(top: 12, bottom: 8),
          child: MiniBarChart(
            title: title,
            items: items.take(maxItems).toList(),
            maxItems: maxItems,
          ),
        );
      },
    );
  }
}

