import 'package:flutter/material.dart';
import '../services/settings_service.dart';
import '../../../shared/widgets/base_scaffold.dart';
import '../../../shared/widgets/app_buttons.dart';

class SettingsScreen extends StatefulWidget {
  const SettingsScreen({super.key});

  @override
  State<SettingsScreen> createState() => _SettingsScreenState();
}

class _SettingsScreenState extends State<SettingsScreen> {
  final _apiController = TextEditingController();
  final _formKey = GlobalKey<FormState>();

  // ★ デフォルトは gpt-4.1-mini
  String _selectedModel = 'gpt-4.1-mini';

  // 出題確率（0〜100）
  int _fiveChoiceProb = 0;
  int _incorrectProb = 0;
  int _multipleProb = 0;

  bool _obscureApi = true;
  bool _loading = true;

  // ★ この画面で選択可能なモデル一覧
  static const Set<String> _supportedModels = {
    'gpt-4.1-mini',
    'gpt-5.1-mini',
    'gpt-5.1',
  };

  @override
  void initState() {
    super.initState();
    _load();
  }

  @override
  void dispose() {
    _apiController.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    final api = await SettingsService.getApiKey();
    final savedModel = await SettingsService.getModel();

    final five = await SettingsService.getFiveChoiceProbability() ?? 0;
    final incorrect = await SettingsService.getIncorrectKindProbability() ?? 0;
    final multiple = await SettingsService.getMultipleKindProbability() ?? 0;

    if (!mounted) return;

    setState(() {
      _apiController.text = api ?? '';

      // ★ 保存済みモデルが items に存在しない場合は安全にフォールバック
      _selectedModel = _supportedModels.contains(savedModel)
          ? savedModel!
          : 'gpt-4.1-mini';

      _fiveChoiceProb = _clampPercent(five);
      _incorrectProb = _clampPercent(incorrect);
      _multipleProb = _clampPercent(multiple);
      _loading = false;
    });
  }

  int _clampPercent(int v) => v.clamp(0, 100);

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;

    await SettingsService.setApiKey(_apiController.text.trim());
    await SettingsService.setModel(_selectedModel);
    await SettingsService.setFiveChoiceProbability(_fiveChoiceProb);
    await SettingsService.setIncorrectKindProbability(_incorrectProb);
    await SettingsService.setMultipleKindProbability(_multipleProb);

    if (!mounted) return;
    FocusScope.of(context).unfocus();

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('設定を保存しました')),
    );
  }

  @override
  Widget build(BuildContext context) {
    return BaseScaffold(
      title: '設定',
      body: SafeArea(
        child: _loading
            ? const Center(child: CircularProgressIndicator())
            : SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(16, 20, 16, 40),
          child: Form(
            key: _formKey,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // ===== APIキー =====
                const Text(
                  'OpenAI APIキー',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 6),

                TextFormField(
                  controller: _apiController,
                  obscureText: _obscureApi,
                  enableSuggestions: false,
                  autocorrect: false,
                  decoration: InputDecoration(
                    border: const OutlineInputBorder(),
                    hintText: 'sk-xxxx…',
                    suffixIcon: IconButton(
                      tooltip: _obscureApi ? '表示' : '非表示',
                      icon: Icon(
                        _obscureApi
                            ? Icons.visibility
                            : Icons.visibility_off,
                      ),
                      onPressed: () =>
                          setState(() => _obscureApi = !_obscureApi),
                    ),
                  ),
                  validator: (v) {
                    final s = (v ?? '').trim();
                    if (s.isEmpty) return null;
                    if (!s.startsWith('sk-')) {
                      return '先頭が「sk-」の形式を推奨します';
                    }
                    return null;
                  },
                ),
                const SizedBox(height: 20),

                // ===== モデル選択 =====
                const Text(
                  'モデル',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 6),
                DropdownButtonFormField<String>(
                  value: _selectedModel,
                  items: const [
                    DropdownMenuItem(
                      value: 'gpt-4.1-mini',
                      child:
                      Text('gpt-4.1-mini（高速・問題生成おすすめ）'),
                    ),
                    DropdownMenuItem(
                      value: 'gpt-5.1-mini',
                      child: Text('gpt-5.1-mini'),
                    ),
                    DropdownMenuItem(
                      value: 'gpt-5.1',
                      child: Text('gpt-5.1（高精度・分析向け）'),
                    ),
                  ],
                  onChanged: (val) {
                    if (val != null) {
                      setState(() => _selectedModel = val);
                    }
                  },
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 30),

                // ===== 出題オプション =====
                const Text(
                  '出題オプション（確率設定）',
                  style: TextStyle(fontWeight: FontWeight.bold),
                ),
                const SizedBox(height: 10),

                _buildSlider(
                  label: '5択が出る確率',
                  value: _fiveChoiceProb,
                  onChanged: (v) => setState(
                          () => _fiveChoiceProb = _clampPercent(v)),
                ),
                const SizedBox(height: 20),

                _buildSlider(
                  label: '誤答（間違いを選べ）問題の確率',
                  value: _incorrectProb,
                  onChanged: (v) => setState(
                          () => _incorrectProb = _clampPercent(v)),
                ),
                const SizedBox(height: 20),

                _buildSlider(
                  label: '複数選択（正解が2つ）問題の確率',
                  value: _multipleProb,
                  onChanged: (v) => setState(
                          () => _multipleProb = _clampPercent(v)),
                ),
                const SizedBox(height: 40),

                // ===== 保存ボタン =====
                SizedBox(
                  width: double.infinity,
                  child: AppButtons.primary(
                    label: '保存',
                    icon: Icons.save,
                    onPressed: _save,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  // ===== スライダー部品 =====
  Widget _buildSlider({
    required String label,
    required int value,
    required ValueChanged<int> onChanged,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label),
        Row(
          children: [
            Expanded(
              child: Slider(
                value: value.toDouble(),
                min: 0,
                max: 100,
                divisions: 20,
                label: '$value%',
                onChanged: (v) => onChanged(v.round()),
              ),
            ),
            SizedBox(
              width: 72,
              child: Text(
                '$value%',
                textAlign: TextAlign.end,
              ),
            ),
          ],
        ),
      ],
    );
  }
}

// lib/features/settings/services/settings_service.dart
import 'package:shared_preferences/shared_preferences.dart';

class SettingsService {
  static const _keyApiKey = 'api_key';
  static const _keyModel = 'model';
  static const _keyChoiceMode = 'choice_mode'; // auto|force4|force5
  static const _keyFiveChoiceProb = 'five_choice_probability';
  static const _keyMultipleProb = 'multiple_kind_probability';
  static const _keyIncorrectProb = 'incorrect_kind_probability';

  // ==========================
  // APIキー / モデル
  // ==========================
  static Future<void> setApiKey(String value) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_keyApiKey, value);
  }

  static Future<String?> getApiKey() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getString(_keyApiKey);
  }

  static Future<void> setModel(String value) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_keyModel, value);
  }

  static Future<String?> getModel() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getString(_keyModel);
  }

  // ==========================
  // 出題設定
  // ==========================
  static Future<void> setChoiceMode(String mode) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_keyChoiceMode, mode);
  }

  static Future<String?> getChoiceMode() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getString(_keyChoiceMode);
  }

  static Future<void> setFiveChoiceProbability(int percent) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt(_keyFiveChoiceProb, percent);
  }

  static Future<int?> getFiveChoiceProbability() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getInt(_keyFiveChoiceProb);
  }

  static Future<void> setMultipleKindProbability(int percent) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt(_keyMultipleProb, percent);
  }

  static Future<int?> getMultipleKindProbability() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getInt(_keyMultipleProb);
  }

  static Future<void> setIncorrectKindProbability(int percent) async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setInt(_keyIncorrectProb, percent);
  }

  static Future<int?> getIncorrectKindProbability() async {
    final prefs = await SharedPreferences.getInstance();
    return prefs.getInt(_keyIncorrectProb);
  }
}

// lib/features/settings/services/version_service.dart
import 'package:package_info_plus/package_info_plus.dart';

/// アプリのバージョンを提供するサービス。
class VersionService {
  /// バージョンを返す（例: "1.0.0"）
  /// ※ 通常は buildNumber は付けません。("1.0.0 (1)" などの (1) を避けるため)
  static Future<String> getAppVersion({bool includeBuild = false}) async {
    final info = await PackageInfo.fromPlatform();
    final version = info.version; // 例: "1.0.0"
    if (includeBuild) {
      final build = info.buildNumber; // 例: "1"
      return '$version+$build';
    }
    return version;
  }

  /// フッター表記に使う整形済み文字列を返す。
  /// 例: "© 2025 NurAI  Ver 1.0.0"
  static Future<String> footerText() async {
    final v = await getAppVersion();
    // 全角スペース混在を避け、半角2つで視認性を確保
    return '© 2025 NurAI  Ver $v';
  }
}
